<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · CompareSlider</h1>
      <p class="demo-page__lead">
        来自 video-code 的「图片对比」：两张图叠在一起，上层用 <code>clip-path</code> 按中线裁掉右半边，
        中间一条发光中线和圆形把手，拖动、方向键、双击回正都能调；原 demo 还带「上传两张图 / 交换 / 重置 /
        自动巡航」这套编辑器。组件只保留对比卡本体（拖动和键盘交给一个透明的 range 输入，无障碍是现成的），
        上传、交换这类操作留在页面里，通过 <code>v-model:position</code> 和 <code>swap()</code> /
        <code>reset()</code> 串起来。
      </p>
    </header>

    <section class="cmp-demo">
      <div class="cmp-demo__head">
        <h2 class="demo-page__section-title">拖中线 · 看前后差别</h2>
        <code class="cmp-demo__tag">{{ position.toFixed(1) }}%</code>
      </div>
      <p class="demo-card__text">
        左右拖动中线（或者点卡片上任意位置直接跳过去），焦点在卡片上时用 ← → 微调，双击回到中间。
        下面两张图是同一场景的「原片 / 调色后」，可以换成你自己的照片。
      </p>

      <div class="cmp-demo__stage">
        <CompareSlider
          ref="sliderRef"
          v-model:position="position"
          :before="before"
          :after="after"
          :auto-sweep="autoSweep"
          before-label="原片"
          after-label="调色后"
          @change="onChange"
        />
      </div>

      <div class="cmp-demo__toolbar">
        <label class="cmp-demo__file">
          上传原片
          <input type="file" accept="image/*" @change="onUpload($event, 'before')" />
        </label>
        <label class="cmp-demo__file">
          上传调色
          <input type="file" accept="image/*" @change="onUpload($event, 'after')" />
        </label>
        <button class="demo-btn demo-btn--ghost" type="button" @click="swap">交换</button>
        <button class="demo-btn demo-btn--ghost" type="button" @click="sliderRef?.reset()">
          重置
        </button>
        <button class="demo-btn" type="button" @click="autoSweep = !autoSweep">
          {{ autoSweep ? '停止巡航' : '自动巡航' }}
        </button>
        <span class="cmp-demo__count">最近一次：<code>{{ lastAction }}</code></span>
      </div>

      <div class="cmp-demo__row">
        <div class="cmp-demo__cell">
          <CompareSlider
            :before="before"
            :after="after"
            :position="28"
            :ratio="4 / 3"
            :show-labels="false"
            :handle-size="44"
            accent="#0f766e"
          />
          <p>4:3 + 不显示标签 + 小把手 + 换主色（<code>ratio</code> / <code>handleSize</code> / <code>accent</code>）</p>
        </div>
        <div class="cmp-demo__cell">
          <CompareSlider
            :before="before"
            :after="after"
            :position="60"
            :ratio="1"
            :handle-size="76"
            :auto-sweep="true"
            :sweep-speed="0.6"
            before-label="BEFORE"
            after-label="AFTER"
          />
          <p>1:1 + 自动巡航（<code>autoSweep</code> / <code>sweepSpeed</code>）</p>
        </div>
      </div>
    </section>

    <DemoPreview class="cmp-preview">
      <LevaPlayground
        name="CompareSlider"
        :component="CompareSlider"
        :schema="CompareSliderSchema"
        :presets="{ before, after, position: 50 }"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        面板里 <code>position</code> 是中线位置（也能直接拖），<code>ratio</code> 是宽高比，
        <code>handleSize</code> 是把手直径，<code>accent</code> 是中线颜色，
        <code>beforeLabel</code> / <code>afterLabel</code> / <code>showLabels</code> 控制两个标签，
        <code>autoSweep</code> + <code>sweepSpeed</code> 是自动巡航。两张图的地址是字符串控件，
        换成别的链接即可。
      </span>
    </p>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue'
import CompareSliderSchema from '@melt-js/comps-vue3/src/components/CompareSlider.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { remoteComponent } from '../configs/remote'

const CompareSlider = remoteComponent('CompareSlider')

/** 同一场景生成两个版本：左边偏灰偏冷（原片），右边加饱和加暖（调色后） */
function scene(variant: 'raw' | 'graded'): string {
  const isRaw = variant === 'raw'
  const sky = isRaw ? ['#9fb0b8', '#c9c3b8'] : ['#3d7ea6', '#f0c08a']
  const hill = isRaw ? '#8a9088' : '#2f6b46'
  const hillBack = isRaw ? '#a5aaa2' : '#5f9a67'
  const sand = isRaw ? '#b6b0a4' : '#e0b276'
  const sunOpacity = isRaw ? '0.28' : '0.6'
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="960" height="540">
    <defs>
      <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="${sky[0]}"/><stop offset="1" stop-color="${sky[1]}"/>
      </linearGradient>
      <linearGradient id="land" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="${hillBack}"/><stop offset="1" stop-color="${hill}"/>
      </linearGradient>
      <linearGradient id="beach" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="${sand}"/><stop offset="1" stop-color="${hill}"/>
      </linearGradient>
    </defs>
    <rect width="960" height="540" fill="url(#sky)"/>
    <circle cx="742" cy="126" r="58" fill="#fff" opacity="${sunOpacity}"/>
    <path d="M0 300 L196 214 L352 292 L520 196 L676 286 L820 226 L960 300 L960 540 L0 540 Z" fill="url(#land)"/>
    <path d="M0 406 L120 372 L268 404 L420 356 L560 398 L700 362 L840 400 L960 368 L960 540 L0 540 Z" fill="url(#beach)" opacity=".92"/>
    <path d="M0 470 Q240 436 480 468 T960 452 L960 540 L0 540 Z" fill="${hill}" opacity=".55"/>
    <text x="58" y="76" font-family="PingFang SC, Microsoft YaHei, sans-serif" font-size="26"
      font-weight="700" fill="rgba(255,255,255,.86)">${isRaw ? '原片 / 未调色' : '调色后 / 暖调'}</text>
  </svg>`
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`
}

const before = ref(scene('raw'))
const after = ref(scene('graded'))
const position = ref(50)
const autoSweep = ref(false)
const lastAction = ref('（还没动过）')
const sliderRef = ref<{ reset: () => void } | null>(null)

const stageStyle = {
  display: 'block',
  height: '520px',
  padding: '24px',
  background: '#f4efe7',
}

function onChange(value: number) {
  lastAction.value = `中线停在 ${value.toFixed(1)}%`
}

function swap() {
  const previous = before.value
  before.value = after.value
  after.value = previous
  lastAction.value = '交换了左右两张图'
}

function onUpload(event: Event, side: 'before' | 'after') {
  const input = event.target as HTMLInputElement
  const file = input.files?.[0]
  if (!file) return
  if (!file.type.startsWith('image/')) {
    input.value = ''
    return
  }
  const reader = new FileReader()
  reader.onload = () => {
    if (side === 'before') before.value = String(reader.result)
    else after.value = String(reader.result)
    lastAction.value = `${side === 'before' ? '原片' : '调色'}换成了 ${file.name}`
  }
  reader.readAsDataURL(file)
  input.value = ''
}
</script>

